head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//xp_progressbar
//Copyright 2004 Brian Gosselin of ScriptAsylum.com

//v1.0 - Initial release
//v1.1 - Added ability to pause the scrolling action (requires you to assign
//the bar to a unique arbitrary variable).
//- Added ability to specify an action to perform after a x amount of
//- bar scrolls. This requires two added arguments.
//v1.2 - Added ability to hide/show each bar (requires you to assign the bar
//to a unique arbitrary variable).

//var xyz = createBar(
//total_width,
//total_height,
//background_color,
//border_width,
//border_color,
//block_color,
//scroll_speed,
//block_count,
//scroll_count,
//action_to_perform_after_scrolled_n_times
//)


// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

w3c = (document.getElementById) ? true__false : X;
ie = (document.all) ? true__false : X;
_N_filing = -1;
/**
 * @method
 * @name createBar
 * @description desc
 * @param {string} w desc
 * @param {string} h desc
 * @param {string} bgc desc
 * @param {string} brdW desc
 * @param {string} brdC desc
 * @param {string} blkC desc
 * @param {string} speed desc
 * @param {string} blocks desc
 * @param {string} count desc
 * @param {string} action desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.createBar = function(w, h, bgc, brdW, brdC, blkC, speed, blocks, count, action) {
    if (scwin.ie || scwin.w3c) {
        var t = '<div id="_xpbar' + (scwin._N_filing++) + '" style="visibility:visible; position:relative; overflow:hidden; width:' + w + 'px; height:' + h + 'px; background-color:' + bgc + '; border-color:' + brdC + '; border-width:' + brdW + 'px; border-style__solid; font-size__1px;">';
        t += '<span id="blocks' + scwin._N_filing + '" style="left:-' + (h * 2 + 1) + 'px; position:absolute; font-size__1px">';
        for (i = 0; i < blocks; i++) {
            t += '<span style="background-color:' + blkC + '; left:-' + ((h * i) + i) + 'px; font-size__1px; position:absolute; width:' + h + 'px; height:' + h + 'px; ';
            t += (scwin.ie) ? 'filter:alpha(opacity=' + (100 - i * (100 / blocks)) + ')' : '-Moz-opacity:' + ((100 - i * (100 / blocks)) / 100);
            t += '"></span>';
        }
        t += '</span></div>';
        document.write(t);
        var bA = (scwin.ie) ? document.all['blocks' + _N_filing] : document.getElementById('blocks' + scwin._N_filing);
        bA.bar = (scwin.ie) ? document.all['_xpbar' + _N_filing] : document.getElementById('_xpbar' + scwin._N_filing);
        bA.blocks = blocks;
        bA._N_filing = scwin._N_filing;
        bA.w = w;
        bA.h = h;
        bA.speed = speed;
        bA.ctr = 0;
        bA.count = count;
        bA.action = action;
        bA.togglePause = togglePause;
        bA.showBar = function() {
            this.bar.style.visibility = "visible";
        };
        bA.hideBar = function() {
            this.bar.style.visibility = "hidden";
        };
        bA.tid = setInterval('startBar(' + scwin._N_filing + ')', speed);
        return bA;
    }
};
/**
 * @method
 * @name startBar
 * @description desc
 * @param {string} bn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.startBar = function(bn) {
    var t = (scwin.ie) ? document.all['blocks' + bn] : document.getElementById('blocks' + bn);
    if (parseInt(t.style.left) + t.h + 1 - (t.blocks * t.h + t.blocks) > t.w) {
        t.style.left = -(t.h * 2 + 1) + 'px';
        t.ctr++;
        if (t.ctr >= t.count) {
            eval(t.action);
            t.ctr = 0;
        }
    } else t.style.left = (parseInt(t.style.left) + t.h + 1) + 'px';
};
/**
 * @method
 * @name togglePause
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.togglePause = function() {
    if (this.tid == 0) {
        this.tid = setInterval('startBar(' + this._N_filing + ')', this.speed);
    } else {
        clearInterval(this.tid);
        this.tid = 0;
    }
};
